import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  FormControlLabel,
  FormHelperText,
  FormLabel,
  Grid,
  IconButton,
  Radio,
  RadioGroup,
  TextField,
} from "@mui/material";
import CloseIcon from "mdi-material-ui/Close";
import { useEffect, useState } from "react";
import { Controller, useForm } from "react-hook-form";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints, MEDIA_URL } from "src/network/endpoints";
import * as yup from "yup";
import { toastError, toastSuccess } from "src/utils/utils";
import UploadIcon from "@mui/icons-material/Upload";
import "react-quill/dist/quill.snow.css";
import CustomFileUploads from "src/views/common/CustomFileUploads";

const validationSchema = yup.object().shape({
  // overview_pdf: yup
  //   .mixed()
  //   .required("Image is required")
  //   .test("fileSize", "Image is required", (value) => {
  //     if (typeof value === "string") return true;
  //     return !value || value.size <= 1024 * 1024 * 3; // 5MB
  //   })
  //   .test("fileType", "Unsupported file format", (value) => {
  //     if (typeof value === "string") return true;
  //     return !value || /image\/(jpeg|jpg|png)/.test(value.type);
  //   }),
});

const DialogOverviewDownload = (props) => {
  const { open, toggle, itSolutionId, onSuccess } = props;

  const [loading, setLoading] = useState(false);

  const {
    control,
    handleSubmit,
    reset,
    formState: { errors },
  } = useForm({
    defaultValues: {
      overview_pdf: "",
    },
    resolver: yupResolver(validationSchema),
    mode: "onChange",
  });

  useEffect(() => {
    if (open) {
      setLoading(false);
    }
  }, [open]);

  const onSubmit = (data) => {
    const payload = new FormData();
    payload.append("overview_pdf", data.overview_pdf);
    payload.append("sub_it_solution_list_id", itSolutionId);

    setLoading(true);

    let apiInstance = null;

    apiInstance = axiosInstance.post(
      ApiEndPoints.ITSolutionOverviewDownload.create,
      payload,
      {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      }
    );

    apiInstance
      .then((response) => response.data)
      .then((response) => {
        onSuccess();
        toastSuccess(response.message);
        toggle();
        reset();
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  return (
    <>
      <Dialog
        open={open}
        onClose={toggle}
        fullWidth
        maxWidth="sm"
        scroll="paper"
      >
        <DialogTitle
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <Box>Add</Box>
          <IconButton
            aria-label="close"
            onClick={toggle}
            sx={{ color: (theme) => theme.palette.grey[500] }}
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent
          sx={{ pb: 8, px: { sx: 8, sm: 15 }, pt: { xs: 8, sm: 12.5 } }}
        >
          <form id="form" onSubmit={handleSubmit(onSubmit)}>
            <Grid container spacing={4}>
              <Grid item xs={12}>
                <FormControl fullWidth>
                  <FormLabel htmlFor="overview_pdf">Upload File</FormLabel>
                  <Controller
                    name="overview_pdf"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <CustomFileUploads
                        multiple={false}
                        minHeight="0px"
                        subtitle="(Max file size 3mb)"
                        files={value}
                        onChange={onChange}
                        title={"Upload "}
                        MediaUrl={MEDIA_URL}
                      />
                    )}
                  />
                </FormControl>
              </Grid>
            </Grid>
          </form>
        </DialogContent>
        <DialogActions>
          <LoadingButton
            size="large"
            type="submit"
            form="form"
            variant="contained"
            loading={loading}
          >
            Submit
          </LoadingButton>
          <Button size="large" variant="outlined" onClick={toggle}>
            Cancel
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default DialogOverviewDownload;
